// Characterization tests: pin CURRENT behaviour of order totals, bugs included.
import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

const prices = { A: 10, B: 25, C: 0.1, D: 33.33, E: 100, F: 101, G: 0.99 }
const pricing = { priceOf: async (sku) => prices[sku] }
let server, base

before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body) => fetch(`${base}/orders`, { method: 'POST', body: JSON.stringify(body) })
const totalOf = async (items) => {
  const res = await post({ items })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

test('no discount at or below 100', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 3 }]), 30)
  assert.equal(await totalOf([{ sku: 'E', qty: 1 }]), 100)
})

test('discount threshold is strictly above 100', async () => {
  assert.equal(await totalOf([{ sku: 'F', qty: 1 }]), 90) // 90.9 floored
})

test('10% discount on whole order above 100', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 11 }]), 99)  // 110 -> 99
  assert.equal(await totalOf([{ sku: 'B', qty: 8 }]), 180)  // 200 -> 180
  assert.equal(await totalOf([{ sku: 'A', qty: 100 }]), 900)
})

test('total is floored, not rounded (BUG: truncates cents, returns integers)', async () => {
  assert.equal(await totalOf([{ sku: 'G', qty: 1 }]), 0)
  assert.equal(await totalOf([{ sku: 'D', qty: 3 }]), 99)   // 99.99 -> 99
  assert.equal(await totalOf([{ sku: 'F', qty: 2 }]), 181)  // 202 -> 181.8 -> 181
})

test('floating point artefacts leak into the total', async () => {
  assert.equal(await totalOf([{ sku: 'C', qty: 3 }]), 0) // 0.30000000000000004
  assert.equal(await totalOf([{ sku: 'C', qty: 1000 }]), 90) // 100.00000000000001 > 100 -> discounted 90.0000..
})

test('multiple lines are summed before discount', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 5 }, { sku: 'B', qty: 3 }]), 112) // 125 -> 112.5
})

test('zero/negative/missing qty are not validated', async () => {
  assert.equal(await totalOf([{ sku: 'A', qty: 0 }]), 0)
  assert.equal(await totalOf([{ sku: 'A', qty: -2 }]), -20)
  assert.equal(await totalOf([{ sku: 'A', qty: 5 }, { sku: 'E', qty: -1 }]), -50)
})

test('unknown sku yields NaN, serialised as null', async () => {
  assert.equal(await totalOf([{ sku: 'ZZZ', qty: 1 }]), null)
})

test('created order is retrievable with same total', async () => {
  const created = await (await post({ items: [{ sku: 'B', qty: 8 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), created)
  assert.deepEqual(created.items, [{ sku: 'B', qty: 8 }])
})

test('validation and routing quirks', async () => {
  assert.equal((await post({})).status, 400)
  assert.equal((await post({ items: [] })).status, 400)
  const bad = await fetch(`${base}/orders`, { method: 'POST', body: '{nope' })
  assert.equal(bad.status, 400)
  const missing = await fetch(`${base}/orders/999`)
  assert.equal(missing.status, 200) // BUG: should be 404
  assert.deepEqual(await missing.json(), { error: 'not found' })
  assert.equal((await fetch(`${base}/nope`)).status, 404)
})
EOF
node --test 2>&1 | grep -E "^# (pass|fail)|not ok|expected|actual" | head -30

